const out = [];
for (const item of $input.all()) {
  const b = item.json.body || item.json;
  const h = item.json.headers || {};
  const event = String(h['x-probo-webhook-event'] || b.eventType || '').toLowerCase();
  const data = b.data || {};
  const prevData = b.updatedFrom || {};
  const curr = String((data.membership && data.membership.state) || data.state || '').toUpperCase();
  const prev = String((prevData.membership && prevData.membership.state) || prevData.state || '').toUpperCase();

  const personEmail = data.emailAddress || data.email || '';
  const personName = data.fullName || data.name || personEmail;
  const organizationId = b.organizationId || h['x-probo-webhook-organization-id'] || data.organizationId || '';

  const becameInactive = event === 'user:updated' && prev === 'ACTIVE' && curr === 'INACTIVE';
  const activeUserDeleted = event === 'user:deleted' && curr === 'ACTIVE';
  const isOffboarding = becameInactive || activeUserDeleted;

  out.push({ json: {
    event: event,
    isOffboarding: isOffboarding,
    offboardingReason: becameInactive ? 'active->inactive' : (activeUserDeleted ? 'deleted-while-active' : 'none'),
    personEmail: personEmail,
    personName: personName,
    organizationId: organizationId,
    currentState: curr,
    previousState: prev
  } });
}
return out;

const norm = $('Normalize Payload for Offboarding').first().json;
const target = String(norm.personEmail || '').toLowerCase();
const personName = norm.personName || norm.personEmail || target;

const created = $('Initiate Probo Access Review').first().json || {};
const campaignId = created.id || (created.data && created.data.createAccessReviewCampaign && created.data.createAccessReviewCampaign.accessReviewCampaignEdge && created.data.createAccessReviewCampaign.accessReviewCampaignEdge.node && created.data.createAccessReviewCampaign.accessReviewCampaignEdge.node.id) || '';

const cfg = $('Set Probo Alert Settings').first().json || {};
const base = String(cfg.proboAppBaseUrl || 'https://app.probo.com').replace(/\/+$/, '');
const campaignUrl = campaignId ? (base + '/access-reviews/' + campaignId) : base;
const fallbackAdmin = cfg.fallbackAdminEmail || '';

const raw = $input.first().json || {};
const root = raw.data || raw;
const cNode = root.node || root;
const edges = (cNode.entries && cNode.entries.edges) || [];
const nodes = Array.isArray(raw.accessReviewEntries) ? raw.accessReviewEntries : edges.map(function (e) { return (e && e.node) || e || {}; });

const activeToolIds = {};
for (const n of nodes) {
  if (String(n.email || '').toLowerCase() === target && n.active === true) {
    const src = n.campaignSource || {};
    activeToolIds[src.id || src.name || 'unknown'] = src.name || 'a connected tool';
  }
}

const adminsByEmail = {};
const toolsWithAdmin = {};
for (const n of nodes) {
  const src = n.campaignSource || {};
  const key = src.id || src.name || 'unknown';
  if (n.isAdmin === true && activeToolIds[key] && n.email && String(n.email).toLowerCase() !== target) {
    const em = String(n.email);
    if (!adminsByEmail[em]) adminsByEmail[em] = { name: n.fullName || em, tools: {} };
    adminsByEmail[em].tools[activeToolIds[key]] = true;
    toolsWithAdmin[key] = true;
  }
}

function buildHtml(nameTo, toolNames) {
  const listHtml = toolNames.map(function (t) { return '<li>' + t + '</li>'; }).join('');
  return '<p>Hi ' + nameTo + ',</p><p>As part of an off-boarding access review, <strong>' + personName + '</strong> (' + target + ') is still <strong>active</strong> in the following tool(s) you administer:</p><ul>' + listHtml + '</ul><p>Please revoke their access, then record your decision in Probo: <a href=' + String.fromCharCode(34) + campaignUrl + String.fromCharCode(34) + '>' + campaignUrl + '</a></p>';
}

const out = [];
for (const em in adminsByEmail) {
  const a = adminsByEmail[em];
  const toolNames = Object.keys(a.tools);
  out.push({ json: {
    adminEmail: em,
    adminName: a.name,
    tools: toolNames,
    isFallback: false,
    personEmail: target,
    personName: personName,
    campaignUrl: campaignUrl,
    emailSubject: 'Access review: revoke ' + personName + ' from ' + toolNames.join(', '),
    emailHtml: buildHtml(a.name, toolNames)
  } });
}

const orphanTools = [];
for (const key in activeToolIds) { if (!toolsWithAdmin[key]) orphanTools.push(activeToolIds[key]); }
if (orphanTools.length && fallbackAdmin) {
  out.push({ json: {
    adminEmail: fallbackAdmin,
    adminName: 'team',
    tools: orphanTools,
    isFallback: true,
    personEmail: target,
    personName: personName,
    campaignUrl: campaignUrl,
    emailSubject: 'Access review: no tool admin found for ' + orphanTools.join(', '),
    emailHtml: buildHtml('team', orphanTools)
  } });
}

return out;

const norm = $('Normalize Payload for Offboarding').first().json;
const target = String(norm.personEmail || '').toLowerCase();
const personName = norm.personName || norm.personEmail || target;

const created = $('Initiate Probo Access Review').first().json || {};
const campaignId = created.id || (created.data && created.data.createAccessReviewCampaign && created.data.createAccessReviewCampaign.accessReviewCampaignEdge && created.data.createAccessReviewCampaign.accessReviewCampaignEdge.node && created.data.createAccessReviewCampaign.accessReviewCampaignEdge.node.id) || '';

const cfg = $('Set Probo Alert Settings').first().json || {};
const base = String(cfg.proboAppBaseUrl || 'https://app.probo.com').replace(/\/+$/, '');
const campaignUrl = campaignId ? (base + '/access-reviews/' + campaignId) : base;

const raw = $input.first().json || {};
const root = raw.data || raw;
const cNode = root.node || root;
const edges = (cNode.entries && cNode.entries.edges) || [];
const nodes = Array.isArray(raw.accessReviewEntries) ? raw.accessReviewEntries : edges.map(function (e) { return (e && e.node) || e || {}; });

const activeToolIds = {};
for (const n of nodes) {
  if (String(n.email || '').toLowerCase() === target && n.active === true) {
    const src = n.campaignSource || {};
    activeToolIds[src.id || src.name || 'unknown'] = src.name || 'a connected tool';
  }
}

const notified = {};
const toolsWithAdmin = {};
for (const n of nodes) {
  const src = n.campaignSource || {};
  const key = src.id || src.name || 'unknown';
  if (n.isAdmin === true && activeToolIds[key] && n.email && String(n.email).toLowerCase() !== target) {
    notified[String(n.email)] = true;
    toolsWithAdmin[key] = true;
  }
}

const toolNames = Object.keys(activeToolIds).map(function (k) { return activeToolIds[k]; });
const stillHasAccess = toolNames.length > 0;
const adminList = Object.keys(notified);
const orphanTools = [];
for (const key in activeToolIds) { if (!toolsWithAdmin[key]) orphanTools.push(activeToolIds[key]); }

let slackText;
if (!stillHasAccess) {
  slackText = ':white_check_mark: Off-boarding access review for ' + personName + ' (' + target + ')\nNo remaining active access found across reviewed tools.\nCampaign: ' + campaignUrl;
} else {
  slackText = ':rotating_light: Off-boarding access review for ' + personName + ' (' + target + ')\nStill active in: ' + toolNames.join(', ');
  slackText += adminList.length ? ('\nAdmins notified: ' + adminList.join(', ')) : '';
  slackText += orphanTools.length ? ('\n:warning: No tool admin found for: ' + orphanTools.join(', ') + ' (sent to fallback)') : '';
  slackText += '\nCampaign: ' + campaignUrl;
}

return [{ json: { stillHasAccess: stillHasAccess, tools: toolNames, adminsNotified: adminList, orphanTools: orphanTools, personEmail: target, personName: personName, campaignUrl: campaignUrl, slackText: slackText } }];
